MATCH (s:PlantItem {tag: "E-2803"}), (t:PlantItem {tag: "P-14501A"})
OPTIONAL MATCH p = shortestPath((s)-[:send_to*]->(t))
RETURN s.tag AS source_tag, t.tag AS target_tag, p IS NOT NULL AS can_reach;

MATCH (tank:PlantItem {tag: "TK-3502"})-[:send_to]-(valve:PlantItem)-[:control]->(actuator:PlantItem)<-[:send_signal_to]-(controller:ProcessControlFunction)
RETURN DISTINCT controller.loop_tag AS loop_tag
ORDER BY loop_tag;

MATCH (e:Equipment {tag: 'E-26801'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (target:PlantItem {tag: 'P-39701'})
MATCH (source:PlantItem)-[:send_to*1..]->(target)
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag

MATCH (item:PlantItem {tag: 'EA-26801'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (source:PlantItem {tag: 'V-901'}), (target:PlantItem {tag: 'E-35601'})
OPTIONAL MATCH path = shortestPath((source)-[:send_to*]->(target))
RETURN source.tag AS source_tag, target.tag AS target_tag, path IS NOT NULL AS process_flow_can_reach;

MATCH (e:Equipment {tag: "E-10601"})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'P-41702'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: "TK-15201"})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
ORDER BY tag

MATCH (i:PlantItem {tag: "ZSC-573006"})
RETURN i.tag AS tag, labels(i) AS item_type, i.dexpi_class AS dexpi_class, i.node_class AS node_class
}

MATCH (v:PlantItem:GateValve)
WHERE toString(v.unit_id) = '180'
RETURN count(v) AS gate_valve_count, collect(v.tag) AS gate_valve_tags;

MATCH (item:PlantItem {tag: "V-9501"})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: "EJ-25501A"})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: 'P-45601A'})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem:CentrifugalPump)
WHERE p.unit_id = '330'
RETURN count(p) AS count, collect(p.tag) AS tags;

MATCH (item:PlantItem {tag: "E-60202"})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (v:SpringLoadedGlobeSafetyValve)
WHERE v.unit_id = '475'
RETURN count(v) AS count, collect(v.tag) AS tags;

MATCH (source:PlantItem)-[:send_to*1..]->(target:Tank {tag: 'TK-40301'})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tagJapgolly

MATCH (source:PlantItem)-[:send_to*1..]->(:PlantItem {tag: 'P-15901C'})
WHERE NOT EXISTS { MATCH ()-[:send_to]->(source) }
RETURN DISTINCT source.tag AS tag

MATCH p = shortestPath(
  (s:PlantItem {tag: "TK-22803"})-[:send_to*1..]->(t:PlantItem {tag: "EJ-59901"})
)
RETURN [n IN nodes(p) | n.tag] AS tags, true AS can_reach
UNION
MATCH (s:PlantItem {tag: "TK-22803"})
WHERE NOT EXISTS {
  MATCH (s)-[:send_to*1..]->(:PlantItem {tag: "EJ-59901"})
}
RETURN [s.tag] AS tags, false AS can_reach
